// Validate and prepare query
const items = $input.all();
const results = [];

for (const item of items) {
  const payload = item.json;
  const query = payload.query?.trim();
  const companyId = payload.companyId;
  const userId = payload.userId;
  const sessionId = payload.sessionId;
  const language = payload.language || 'vi';

  // Validation
  if (!query || query.length === 0) {
    throw new Error('Query cannot be empty');
  }
  if (query.length > 5000) {
    throw new Error('Query exceeds maximum length of 5000 characters');
  }
  if (!companyId) {
    throw new Error('Company ID is required');
  }

  results.push({
    json: {
      query,
      companyId,
      userId,
      sessionId,
      language,
      timestamp: new Date().toISOString()
    }
  });
}

return results;

// Prepare Pinecone Query
const items = $input.all();
const results = [];

for (const item of items) {
  const embeddingResponse = item.json;
  const queryData = $('Validate Query').first().json;

  const embedding = embeddingResponse.data?.[0]?.embedding;

  if (!embedding) {
    throw new Error('No embedding returned from Azure OpenAI');
  }

  // Pinecone query payload with namespace and filters
  const pineconeQuery = {
    vector: embedding,
    topK: 10,
    includeMetadata: true,
    namespace: `company-${queryData.companyId}`,
    filter: {
      companyId: queryData.companyId
    }
  };

  results.push({
    json: {
      pineconeQuery,
      originalQuery: queryData.query,
      companyId: queryData.companyId,
      userId: queryData.userId,
      sessionId: queryData.sessionId,
      language: queryData.language
    }
  });
}

return results;

// Build Context and Citations from Pinecone Results
const items = $input.all();
const results = [];
const SCORE_THRESHOLD = 0.7;

for (const item of items) {
  const pineconeResponse = item.json;
  const queryData = $('Prepare Pinecone Query').first().json;

  const matches = pineconeResponse.matches || [];

  // Filter by score threshold
  const relevantMatches = matches.filter(m => m.score >= SCORE_THRESHOLD);

  // Build context string for LLM
  let contextParts = [];
  let citations = [];
  let totalScore = 0;

  for (const match of relevantMatches) {
    const meta = match.metadata || {};
    totalScore += match.score;

    // Add to context
    contextParts.push(`
[Voucher: ${meta.voucherNumber}]
Ngày: ${meta.voucherDate || 'N/A'}
Mô tả: ${meta.description || 'N/A'}
Tổng Nợ: ${meta.totalDebit || 0} VND
Tổng Có: ${meta.totalCredit || 0} VND
${meta.voucherText ? `Chi tiết: ${meta.voucherText.substring(0, 500)}` : ''}
---`);

    // Add citation
    citations.push({
      entityType: meta.entityType || 'voucher',
      entityId: match.id.replace('voucher-', ''),
      voucherNumber: meta.voucherNumber,
      excerpt: meta.description || meta.voucherText?.substring(0, 100),
      relevanceScore: match.score,
      link: `/vouchers/${match.id.replace('voucher-', '')}`
    });
  }

  const avgScore = relevantMatches.length > 0 ? totalScore / relevantMatches.length : 0;
  const confidence = (avgScore * 0.7) + (Math.min(relevantMatches.length, 5) / 5 * 0.3);

  results.push({
    json: {
      context: contextParts.join('\n'),
      citations,
      confidence,
      matchCount: relevantMatches.length,
      totalMatches: matches.length,
      originalQuery: queryData.originalQuery,
      companyId: queryData.companyId,
      userId: queryData.userId,
      sessionId: queryData.sessionId,
      language: queryData.language
    }
  });
}

return results;

// Check confidence and prepare LLM prompt
const items = $input.all();
const results = [];
const LOW_CONFIDENCE_THRESHOLD = 0.5;

for (const item of items) {
  const data = item.json;

  // Low confidence - return fallback response
  if (data.confidence < LOW_CONFIDENCE_THRESHOLD || data.matchCount === 0) {
    results.push({
      json: {
        skipLLM: true,
        answer: 'Không đủ dữ liệu để trả lời câu hỏi này. Vui lòng thử:\n- Đặt câu hỏi cụ thể hơn về số phiếu hoặc khoảng thời gian\n- Kiểm tra xem các phiếu kế toán liên quan đã được nhập chưa\n- Liên hệ quản trị viên nếu cần hỗ trợ thêm',
        citations: [],
        confidence: data.confidence,
        originalQuery: data.originalQuery,
        companyId: data.companyId,
        userId: data.userId,
        sessionId: data.sessionId
      }
    });
    continue;
  }

  // Build system prompt for Vietnamese accounting assistant
  const systemPrompt = `Bạn là trợ lý kế toán AI chuyên nghiệp, hỗ trợ người dùng tìm hiểu thông tin về các phiếu kế toán và giao dịch tài chính.

Quy tắc:
1. Trả lời bằng tiếng Việt, ngắn gọn và chính xác
2. Chỉ sử dụng thông tin từ ngữ cảnh được cung cấp
3. Nếu không chắc chắn, nói rõ "Dựa trên dữ liệu hiện có..."
4. Đề cập đến số phiếu cụ thể khi có thể
5. Sử dụng định dạng số tiền VND với dấu phẩy (ví dụ: 10,000,000 VND)
6. Không bịa thông tin không có trong ngữ cảnh`;

  const userPrompt = `Ngữ cảnh từ hệ thống kế toán:
${data.context}

Câu hỏi của người dùng: ${data.originalQuery}

Hãy trả lời câu hỏi dựa trên ngữ cảnh trên.`;

  results.push({
    json: {
      skipLLM: false,
      systemPrompt,
      userPrompt,
      context: data.context,
      citations: data.citations,
      confidence: data.confidence,
      originalQuery: data.originalQuery,
      companyId: data.companyId,
      userId: data.userId,
      sessionId: data.sessionId
    }
  });
}

return results;

