// Format final response with LLM answer
const items = $input.all();
const results = [];

for (const item of items) {
  const llmResponse = item.json;
  const promptData = $('Prepare LLM Prompt').first().json;

  const answer = llmResponse.choices?.[0]?.message?.content || 'Không thể tạo câu trả lời. Vui lòng thử lại.';

  // Determine confidence level label
  let confidenceLabel;
  if (promptData.confidence >= 0.8) {
    confidenceLabel = 'high';
  } else if (promptData.confidence >= 0.5) {
    confidenceLabel = 'medium';
  } else {
    confidenceLabel = 'low';
  }

  results.push({
    json: {
      success: true,
      answer,
      citations: promptData.citations,
      confidence: promptData.confidence,
      confidenceLabel,
      query: promptData.originalQuery,
      companyId: promptData.companyId,
      userId: promptData.userId,
      sessionId: promptData.sessionId,
      responseTimeMs: Date.now() - new Date($('Validate Query').first().json.timestamp).getTime(),
      usage: llmResponse.usage || {}
    }
  });
}

return results;

// Format low-confidence fallback response
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  results.push({
    json: {
      success: true,
      answer: data.answer,
      citations: data.citations,
      confidence: data.confidence,
      confidenceLabel: 'low',
      query: data.originalQuery,
      companyId: data.companyId,
      userId: data.userId,
      sessionId: data.sessionId,
      responseTimeMs: Date.now() - new Date($('Validate Query').first().json.timestamp).getTime()
    }
  });
}

return results;

// Merge responses from both branches
const items = $input.all();
return items;

// Error Handler
const items = $input.all();
const queryData = $('Validate Query').first()?.json || {};

console.error('RAG Query failed:', {
  error: items[0]?.json?.error || 'Unknown error',
  query: queryData.query,
  companyId: queryData.companyId,
  timestamp: new Date().toISOString()
});

return [{
  json: {
    success: false,
    answer: 'Đã xảy ra lỗi khi xử lý câu hỏi. Vui lòng thử lại sau hoặc liên hệ quản trị viên.',
    citations: [],
    confidence: 0,
    confidenceLabel: 'error',
    query: queryData.query,
    companyId: queryData.companyId,
    error: items[0]?.json?.error || 'Unknown error'
  }
}];
